'use client';
import { useEffect, useId, useMemo, useRef, useState, type CSSProperties } from 'react';
import { createSequence, duration as D, useIsomorphicLayoutEffect, useStudioMotion } from '../../motion';
import type { EffectProps } from '../../types';
import styles from './styles.module.css';

type Params = { latency: number; stagger: number; rows: number; shimmer: string; speed: number };
type Phase = 'loading' | 'handoff' | 'ready';
type Art = 'sun' | 'stripes' | 'moon' | 'dots' | 'arch' | 'split';
interface Item { title: string; author: string; minutes: number; topic: string; art: Art }

/** Sample data: fictional articles and authors. */
const POOL: readonly Item[] = [
  { title: 'Why every kitchen ends up with exactly one junk drawer', author: 'Ines Okafor', minutes: 6, topic: 'Home', art: 'sun' },
  { title: 'A field guide to the clouds above a commuter train', author: 'Tomas Brekke', minutes: 9, topic: 'Weather', art: 'stripes' },
  { title: 'The slow return of the neighbourhood repair café', author: 'Priya Lindgren', minutes: 5, topic: 'Cities', art: 'moon' },
  { title: 'Keeping a sourdough starter alive through a dark winter', author: 'Wen Adeyemi', minutes: 7, topic: 'Food', art: 'dots' },
  { title: 'What a lighthouse logbook teaches about paying attention', author: 'Ada Moreau', minutes: 11, topic: 'History', art: 'arch' },
  { title: 'How to read a bus timetable like a short novel', author: 'Kofi Sandoval', minutes: 4, topic: 'Transit', art: 'split' },
];

/** One rounded rectangle as an SVG path (clockwise), so several can be unioned in one clip-path. */
function roundedRect(x: number, y: number, w: number, h: number, radius: number): string {
  const r = Math.max(0, Math.min(radius, w / 2, h / 2));
  const n = (v: number) => Math.round(v * 100) / 100;
  return `M${n(x + r)} ${n(y)}H${n(x + w - r)}A${n(r)} ${n(r)} 0 0 1 ${n(x + w)} ${n(y + r)}V${n(y + h - r)}A${n(r)} ${n(r)} 0 0 1 ${n(x + w - r)} ${n(y + h)}H${n(x + r)}A${n(r)} ${n(r)} 0 0 1 ${n(x)} ${n(y + h - r)}V${n(y + r)}A${n(r)} ${n(r)} 0 0 1 ${n(x + r)} ${n(y)}Z`;
}

export default function SkeletonShimmerHandoff({ params }: EffectProps<Params>) {
  const { reduced, scale } = useStudioMotion();
  const uid = useId();
  const rows = Math.round(params.rows);
  const [phase, setPhase] = useState<Phase>('loading');
  const [batch, setBatch] = useState(0);
  const [status, setStatus] = useState('Loading reading list…');
  const listRef = useRef<HTMLUListElement>(null);
  const shimmerRef = useRef<HTMLDivElement>(null);
  const items = useMemo(() => Array.from({ length: rows }, (_, i) => POOL[(batch * 2 + i) % POOL.length]), [rows, batch]);
  const shimmer = !reduced && params.shimmer !== 'none' && phase !== 'ready';
  const busy = phase !== 'ready';

  // 1 · Simulated request.
  useEffect(() => {
    if (phase !== 'loading') return;
    const t = window.setTimeout(() => setPhase('handoff'), params.latency);
    return () => window.clearTimeout(t);
  }, [phase, batch, params.latency]);

  // 2 · Clip the single shimmer layer to the union of every bone. Rebuilt on resize only, never per frame.
  useIsomorphicLayoutEffect(() => {
    const host = shimmerRef.current;
    const list = listRef.current;
    if (!shimmer || !host || !list) return;
    let raf = 0;
    const measure = () => {
      raf = 0;
      const o = host.getBoundingClientRect();
      const d: string[] = [];
      list.querySelectorAll<HTMLElement>('[data-bone]').forEach((el) => {
        const r = el.getBoundingClientRect();
        if (r.width < 1 || r.height < 1) return;
        d.push(roundedRect(r.left - o.left, r.top - o.top, r.width, r.height, parseFloat(getComputedStyle(el).borderTopLeftRadius) || 0));
      });
      host.style.clipPath = d.length ? `path('${d.join('')}')` : 'inset(50%)';
      host.dataset.ready = '';
    };
    measure();
    const ro = typeof ResizeObserver === 'undefined' ? null : new ResizeObserver(() => { if (!raf) raf = requestAnimationFrame(measure); });
    ro?.observe(list);
    return () => { ro?.disconnect(); if (raf) cancelAnimationFrame(raf); };
  }, [shimmer, rows, batch]);

  // 3 · Handoff: shimmer off, then each row cross-fades skeleton → content in the same grid cell.
  useIsomorphicLayoutEffect(() => {
    const list = listRef.current;
    if (phase !== 'handoff' || !list) return;
    const content = list.querySelectorAll('[data-layer="content"]');
    const bones = list.querySelectorAll('[data-layer="skeleton"]');
    const seq = createSequence(reduced ? {} : { durationScale: scale.duration });
    if (reduced) {
      seq.add(content, [{ opacity: 0 }, { opacity: 1 }], { duration: 160, easing: 'linear', at: 0 });
      seq.add(bones, [{ opacity: 1 }, { opacity: 0 }], { duration: 160, easing: 'linear', at: 0 });
    } else {
      const each = params.stagger * scale.stagger;
      seq.add(shimmerRef.current, [{ opacity: 1 }, { opacity: 0 }], { duration: D.fast, easing: 'standard', at: 0 });
      seq.add(bones, [{ opacity: 1 }, { opacity: 0 }], { duration: D.base, easing: 'standard', stagger: each, at: 40 });
      seq.add(content, [{ opacity: 0, transform: 'translateY(6px)' }, { opacity: 1, transform: 'translateY(0)' }], { duration: D.moderate, easing: 'emphasized', stagger: each, at: 40 });
    }
    let live = true;
    void seq.play().then((finished) => {
      if (!live || !finished) return;
      setPhase('ready');
      setStatus(`Reading list loaded: ${rows} ${rows === 1 ? 'article' : 'articles'}.`);
    });
    return () => { live = false; seq.cancel(); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [phase]);

  const reload = () => {
    if (busy) return;
    setBatch((b) => b + 1);
    setPhase('loading');
    setStatus('Loading reading list…');
  };

  return (
    <div className={styles.root} data-reduced={reduced || undefined} data-shimmer={params.shimmer} style={{ '--speed': `${params.speed}ms` } as CSSProperties}>
      <section className={styles.card} aria-labelledby={`${uid}title`}>
        <header className={styles.head}>
          <div>
            <h3 id={`${uid}title`} className={styles.title}>Reading list</h3>
            <p className={styles.sub}>Sample data · fictional articles</p>
          </div>
          <button type="button" className={styles.reload} onClick={reload} aria-disabled={busy || undefined}>
            <svg viewBox="0 0 24 24" width="16" height="16" aria-hidden="true" focusable="false">
              <path d="M19.5 12a7.5 7.5 0 1 1-2.2-5.3M19.5 4.5v4h-4" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
            Reload
          </button>
        </header>
        <p className={styles.status} role="status">{status}</p>

        <div className={styles.listWrap}>
          <ul ref={listRef} className={styles.list} aria-busy={busy} aria-labelledby={`${uid}title`}>
            {items.map((item, i) => (
              <li key={`${batch}-${i}`} className={styles.row}>
                {phase !== 'loading' ? (
                  <article data-layer="content" className={styles.layer}>
                    <span className={styles.thumb} data-art={item.art} aria-hidden="true" />
                    <div className={styles.text}>
                      <h4 className={styles.itemTitle}>{item.title}</h4>
                      <p className={styles.meta}>{item.author} · {item.minutes} min · {item.topic}</p>
                    </div>
                  </article>
                ) : null}
                {phase !== 'ready' ? (
                  <div data-layer="skeleton" className={styles.layer} aria-hidden="true">
                    <span data-bone="" className={styles.thumb} />
                    <div className={styles.text}>
                      <span className={styles.boneTitle}>
                        <span data-bone="" style={{ width: '94%' }} />
                        <span data-bone="" style={{ width: `${46 + ((i * 17) % 30)}%` }} />
                      </span>
                      <span className={styles.boneMeta}><span data-bone="" style={{ width: `${32 + ((i * 11) % 18)}%` }} /></span>
                    </div>
                  </div>
                ) : null}
              </li>
            ))}
          </ul>
          {shimmer ? <div ref={shimmerRef} className={styles.shimmer} aria-hidden="true" /> : null}
        </div>
      </section>
    </div>
  );
}

.root {
  /* Bones are a quiet ink tint of the surface; the glint is always lighter than the bones, in both themes. */
  --sk-base: color-mix(in oklab, var(--mk-ink, #11110f) 9%, var(--mk-surface, #fbf9f4));
  --sk-hi: light-dark(rgb(255 255 255 / 0.78), rgb(255 255 255 / 0.1));
  box-sizing: border-box;
  container-type: inline-size;
  width: min(100% - 2rem, 36rem);
  margin: clamp(1.25rem, 4cqi, 2.5rem) auto;
  color: var(--mk-ink, #11110f);
  font-family: var(--mk-font-text, ui-sans-serif, system-ui, sans-serif);
}
.card {
  padding: clamp(1rem, 5cqi, 1.75rem);
  border: 1px solid var(--mk-line, #11110f24);
  border-radius: var(--mk-radius-l, 18px);
  background: var(--mk-surface, #fbf9f4);
}
.head { display: flex; align-items: flex-start; justify-content: space-between; gap: 1rem; }
.title {
  margin: 0;
  font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: clamp(1.375rem, 5.5cqi, 1.75rem);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.03em;
}
.sub, .status {
  margin: 0.375rem 0 0;
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--mk-ink-muted, #5c5a52);
}
.status { margin-top: 1rem; min-height: 1.5em; text-transform: none; letter-spacing: 0.02em; font-size: 0.75rem; }
.reload {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  min-height: 2.5rem;
  padding: 0 1rem 0 0.875rem;
  border: 1px solid var(--mk-line-strong, #11110f);
  border-radius: 999px;
  background: transparent;
  color: var(--mk-ink, #11110f);
  font: inherit;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
}
.reload:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 2px; }
@media (hover: hover) { .reload:not([aria-disabled='true']):hover { background: var(--mk-surface-2, #e9e5da); } }
.reload[aria-disabled='true'] { cursor: progress; color: var(--mk-ink-muted, #5c5a52); border-color: var(--mk-ink-muted, #5c5a52); }

/* ── List: skeleton and content share each row's grid cell ───────────── */
.listWrap { position: relative; margin-top: 0.5rem; }
.list { display: grid; margin: 0; padding: 0; list-style: none; }
.row { display: grid; padding: 0.875rem 0; border-top: 1px solid var(--mk-line, #11110f24); }
.layer {
  grid-area: 1 / 1;
  display: grid;
  grid-template-columns: 4rem minmax(0, 1fr);
  gap: 1rem;
  align-items: start;
  margin: 0;
}
.layer[data-layer='skeleton'] { animation: bonesIn var(--mk-duration-fast, 160ms) linear both; }
@keyframes bonesIn { from { opacity: 0; } }
.thumb { display: block; width: 4rem; aspect-ratio: 1; border-radius: 10px; background: var(--sk-base); }
.text { display: grid; gap: 0.25rem; min-width: 0; }

/* Geometry is locked to line boxes: 2 title lines + 1 meta line, in both layers. */
.itemTitle, .boneTitle { font-size: 1.0625rem; line-height: 1.3; }
.meta, .boneMeta { font-size: 0.8125rem; line-height: 1.45; }
.itemTitle {
  display: -webkit-box;
  min-height: 2lh;
  margin: 0;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  font-weight: 600;
  letter-spacing: -0.01em;
  text-wrap: pretty;
}
.meta {
  height: 1lh;
  margin: 0;
  overflow: hidden;
  color: var(--mk-ink-muted, #5c5a52);
  white-space: nowrap;
  text-overflow: ellipsis;
}
.boneTitle, .boneMeta { display: grid; align-content: start; }
.boneTitle { height: 2lh; }
.boneMeta { height: 1lh; }
.boneTitle > span, .boneMeta > span { display: block; border-radius: 999px; background: var(--sk-base); }
.boneTitle > span { height: 0.62em; margin-block: calc((1lh - 0.62em) / 2); }
.boneMeta > span { height: 0.6em; margin-block: calc((1lh - 0.6em) / 2); }

@container (max-width: 24rem) {
  .layer { grid-template-columns: 3.25rem minmax(0, 1fr); gap: 0.75rem; }
  .thumb { width: 3.25rem; }
}

/* ── One shimmer layer for the whole list (clip-path = union of bones) ── */
.shimmer { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
.shimmer:not([data-ready]) { visibility: hidden; }
.shimmer::after { content: ''; position: absolute; inset: 0; }
.root[data-shimmer='sweep'] .shimmer::after {
  background: linear-gradient(100deg, transparent 28%, var(--sk-hi) 50%, transparent 72%);
  transform: translateX(-100%);
  animation: sweep var(--speed, 1700ms) var(--mk-ease-inOut, ease-in-out) infinite;
}
.root[data-shimmer='pulse'] .shimmer::after {
  background: var(--sk-hi);
  opacity: 0;
  animation: pulse var(--speed, 1700ms) var(--mk-ease-inOut, ease-in-out) infinite;
}
@keyframes sweep { 0% { transform: translateX(-100%); } 72%, 100% { transform: translateX(100%); } }
@keyframes pulse { 0%, 100% { opacity: 0; } 50% { opacity: 0.7; } }

/* ── Procedural thumbnails (decorative) ──────────────────────────────── */
.thumb[data-art] { background-color: var(--mk-surface-2, #e9e5da); }
.thumb[data-art='sun'] {
  background:
    radial-gradient(circle at 38% 40%, var(--mk-signal, #bf2f09) 0 32%, transparent 33%),
    linear-gradient(to top, var(--mk-ink, #11110f) 0 24%, transparent 24%),
    var(--mk-surface-2, #e9e5da);
}
.thumb[data-art='stripes'] { background: repeating-linear-gradient(135deg, var(--mk-ink, #11110f) 0 3px, transparent 3px 10px), var(--mk-surface-2, #e9e5da); }
.thumb[data-art='moon'] {
  background:
    radial-gradient(circle at 62% 44%, var(--mk-surface-2, #e9e5da) 0 27%, transparent 28%),
    radial-gradient(circle at 50% 50%, var(--mk-signal, #bf2f09) 0 36%, transparent 37%),
    var(--mk-surface-2, #e9e5da);
}
.thumb[data-art='dots'] { background: radial-gradient(var(--mk-ink, #11110f) 1.6px, transparent 1.9px) 0 0 / 9px 9px, var(--mk-surface-2, #e9e5da); }
.thumb[data-art='arch'] {
  background: radial-gradient(circle at 50% 100%, var(--mk-signal, #bf2f09) 0 44%, var(--mk-ink, #11110f) 44% 58%, transparent 58%), var(--mk-surface-2, #e9e5da);
}
.thumb[data-art='split'] {
  background:
    linear-gradient(90deg, var(--mk-ink, #11110f) 0 50%, transparent 50%),
    radial-gradient(circle at 50% 50%, var(--mk-signal, #bf2f09) 0 30%, transparent 31%),
    var(--mk-surface-2, #e9e5da);
}
